"""The tool table of docs/reference/tools.md is generated by scripts/gen_tool_matrix.py."""

from __future__ import annotations

import importlib.util
from pathlib import Path
from types import ModuleType

import pytest

from awa.toolkits import catalog

ROOT = Path(__file__).resolve().parents[2]
SCRIPT = ROOT / "scripts" / "gen_tool_matrix.py"
PAGE = ROOT / "docs" / "reference" / "tools.md"

pytestmark = pytest.mark.skipif(not PAGE.parent.is_dir(), reason="docs/ is in the repository only")


def generator() -> ModuleType:
    spec = importlib.util.spec_from_file_location("gen_tool_matrix", SCRIPT)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def test_the_checked_in_matrix_is_what_the_generator_writes() -> None:
    expected = generator().render()
    assert PAGE.read_text("utf-8").replace("\r\n", "\n") == expected, (
        "docs/reference/tools.md is out of date: run python scripts/gen_tool_matrix.py"
    )


def test_no_row_of_the_matrix_is_missing_an_example_or_a_contract() -> None:
    text = PAGE.read_text("utf-8")
    assert "**missing**" not in text
    rows = [line for line in text.splitlines() if line.startswith("| `")]
    assert len(rows) == len(catalog())


def test_the_generator_reports_a_tool_without_an_example(monkeypatch: pytest.MonkeyPatch) -> None:
    module = generator()
    monkeypatch.setattr(module, "example_titles", lambda: set())
    assert module.table().count("**missing**") == len(catalog())


def test_check_mode_exits_one_for_a_stale_page(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]
) -> None:
    module = generator()
    stale = tmp_path / "tools.md"
    stale.write_text(PAGE.read_text("utf-8").replace("| `", "| `old", 1), encoding="utf-8")
    monkeypatch.setattr(module, "TARGET", stale)
    monkeypatch.setattr("sys.argv", ["gen_tool_matrix.py", "--check"])
    assert module.main() == 1
    assert "out of date" in capsys.readouterr().out
